package com.bank.spark.model;

// Describes a skew situation so a technique can be recommended.
public class SkewProfile {
    private final String name;
    private final int hotKeyCount;
    private final boolean hotKeysKnown;
    private final boolean onlyNeedsAggregate;

    public SkewProfile(String name, int hotKeyCount, boolean hotKeysKnown, boolean onlyNeedsAggregate) {
        this.name = name;
        this.hotKeyCount = hotKeyCount;
        this.hotKeysKnown = hotKeysKnown;
        this.onlyNeedsAggregate = onlyNeedsAggregate;
    }

    public String getName() { return name; }
    public int getHotKeyCount() { return hotKeyCount; }
    public boolean isHotKeysKnown() { return hotKeysKnown; }
    public boolean isOnlyNeedsAggregate() { return onlyNeedsAggregate; }
}
