package com.bank.spark.service;

import com.bank.spark.model.SkewProfile;
import java.util.logging.Logger;

// Recommends a skew-handling technique in a sensible priority order.
public class SkewTechniqueAdvisor {

    private static final Logger log = Logger.getLogger(SkewTechniqueAdvisor.class.getName());
    private static final int FEW_HOT_KEYS = 10;

    public String recommend(SkewProfile p) {
        // 1) Only an aggregate is needed → shrink data before the shuffle.
        if (p.isOnlyNeedsAggregate()) {
            log.info(() -> p.getName() + ": pre-aggregate before join (map-side combine)");
            return "PRE-AGGREGATE — reduce data on the hot key before the shuffle";
        }
        // 2) A few known hot keys → isolate and broadcast them separately.
        if (p.isHotKeysKnown() && p.getHotKeyCount() <= FEW_HOT_KEYS) {
            log.info(() -> p.getName() + ": isolate-and-broadcast " + p.getHotKeyCount() + " hot keys");
            return "ISOLATE-AND-BROADCAST — remove the hot key from the shuffle path";
        }
        // 3) Many moderate hot keys colliding → more shuffle partitions.
        log.info(() -> p.getName() + ": increase shuffle parallelism to spread colliding keys");
        return "INCREASE-PARALLELISM — more shuffle partitions reduce key collisions";
    }
}
