package com.bank.spark;

import com.bank.spark.model.SkewProfile;
import com.bank.spark.service.SkewTechniqueAdvisor;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: recommend a skew technique for each banking scenario.
public class SkewTechniquesDemo {

    private static final Logger log = Logger.getLogger(SkewTechniquesDemo.class.getName());

    // Clean, timestamped log formatter used across the banking demos.
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SkewTechniqueAdvisor advisor = new SkewTechniqueAdvisor();

        List<SkewProfile> situations = List.of(
            new SkewProfile("txn-join-pooling-account", 1, true, false),
            new SkewProfile("merchant-collisions", 40, false, false),
            new SkewProfile("per-account-counts", 1, true, true));

        for (SkewProfile s : situations) {
            String technique = advisor.recommend(s);
            log.info(() -> "Scenario " + s.getName() + " → " + technique);
        }
        log.info("Skew technique recommendations complete.");
    }
}
